(function () {
'use strict';
function boot() {
var U = window.U;
var Tools = window.Tools || {};
var RV = window.ToolCore && window.ToolCore.ResultView;
var Core = window.Core;
var form = document.getElementById('bcForm');
if (!form || !U || !Tools.buyCar || !RV || !Core) return;
var $ = function (id) { return document.getElementById(id); };
var lastResult = null;
function status(message, isError) {
$('bc-status').textContent = message || '';
$('bc-status').hidden = !message;
$('bc-status').classList.toggle('is-error', !!isError);
}
function toggledValue(id, switchId) {
return $(switchId).checked ? $(id).value : 0;
}
function readInput() {
return {
guidePrice: $('bc-guide').value,
invoicePrice: $('bc-invoice').value,
invoicePriceExVat: $('bc-invoice-ex').value,
vatRatePct: $('bc-vat').value,
purchaseDate: $('bc-date').value,
energyType: $('bc-energy').value,
taxReductionEligible: $('bc-eligible').checked,
seats: $('bc-seats').value,
downPct: $('bc-down').value,
annualRatePct: $('bc-rate').value,
years: $('bc-years').value,
registrationFee: toggledValue('bc-registration', 'bc-registration-on'),
serviceFee: toggledValue('bc-service', 'bc-service-on'),
decorationFee: toggledValue('bc-decoration', 'bc-decoration-on'),
chargerFee: toggledValue('bc-charger', 'bc-charger-on'),
otherPurchaseFees: toggledValue('bc-other-purchase', 'bc-other-purchase-on'),
compulsoryInsurance: toggledValue('bc-compulsory', 'bc-compulsory-on'),
commercialInsurance: toggledValue('bc-commercial', 'bc-commercial-on'),
vehicleVesselTax: toggledValue('bc-vessel', 'bc-vessel-on'),
holdYears: $('bc-hold-years').value,
annualKm: $('bc-km').value,
energyUsePer100: $('bc-energy-use').value,
energyPrice: $('bc-energy-price').value,
maintenancePerYear: $('bc-maintenance').value,
parkingPerMonth: $('bc-parking').value,
otherAnnualCost: $('bc-other-annual').value,
renewalInsurancePerYear: $('bc-renewal-insurance').value,
monthlyIncome: $('bc-income').value,
otherMonthlyExpense: $('bc-expense').value,
};
}
function clearResult() {
lastResult = null;
$('bc-result').hidden = true;
$('bc-monthly').textContent = '--';
$('bc-upfront').textContent = '--';
$('bc-loan-total').textContent = '--';
$('bc-cash-total').textContent = '--';
RV.clear($('bc-detail'));
RV.clear($('bc-explain'));
RV.clear($('bc-error'));
$('bc-to-plan').href = '#';
$('bc-to-usage').href = '#';
status('');
}
function syncEnergyFields() {
var ev = $('bc-energy').value === 'ev';
$('bc-eligible-wrap').hidden = !ev;
if (!ev) $('bc-eligible').checked = false;
$('bc-energy-use-label').textContent = ev ? '百公里电耗' : '百公里油耗';
$('bc-energy-use-unit').textContent = ev ? 'kWh/100km' : 'L/100km';
$('bc-energy-price-label').textContent = ev ? '充电单价' : '燃油单价';
$('bc-energy-price-unit').textContent = ev ? '元/kWh' : '元/L';
}
function syncCostToggles() {
[
['bc-registration', 'bc-registration-on'],
['bc-service', 'bc-service-on'],
['bc-decoration', 'bc-decoration-on'],
['bc-charger', 'bc-charger-on'],
['bc-other-purchase', 'bc-other-purchase-on'],
['bc-compulsory', 'bc-compulsory-on'],
['bc-commercial', 'bc-commercial-on'],
['bc-vessel', 'bc-vessel-on'],
].forEach(function (pair) {
$(pair[0]).disabled = !$(pair[1]).checked;
});
}
function displayValue(item) {
if (typeof item.value !== 'number') return item.value;
if (item.note === '%') return String(U.round(item.value, 2));
if (item.note.indexOf('元') === 0) return U.money(item.value);
return U.round(item.value, 2);
}
function optionalNumber(id) {
var value = $(id).value.trim();
if (value === '') return null;
var n = Number(value);
return isFinite(n) && n >= 0 ? n : null;
}
function updateLinks(metrics) {
var values = {
'lp-debt': U.round(metrics.monthlyPayment, 2),
'lp-income': optionalNumber('bc-income'),
'lp-expense': U.round(optionalNumber('bc-expense') + metrics.monthlyOwnershipCost, 2),
};
$('bc-to-plan').href = Core.bridge.link('/combo/life-plan.html', values, { source: 'buy-car' });
$('bc-to-usage').href = Core.bridge.link('/combo/life-plan.html', {
'lp-expense': U.round(metrics.monthlyOwnershipCost, 2),
}, { source: 'buy-car' });
}
function show(result) {
RV.renderError($('bc-error'), result);
if (result.status !== 'success') {
clearResult();
RV.renderError($('bc-error'), result);
status(result.errors.join('；'), true);
return;
}
lastResult = result;
var m = result.metrics;
$('bc-monthly').textContent = U.money(m.monthlyPayment);
$('bc-upfront').textContent = U.money(m.cashUpfront);
$('bc-loan-total').textContent = U.money(m.loanOwnershipTotal);
$('bc-cash-total').textContent = U.money(m.fullCashOwnershipTotal);
RV.renderDetails($('bc-detail'), result.details.map(function (item) {
return { label: item.label, value: displayValue(item), note: item.note };
}));
RV.renderExplanation($('bc-explain'), result);
updateLinks(m);
$('bc-result').hidden = false;
status(m.taxReductionEligible ? '已按符合条件的新能源乘用车减半且受 1.5 万元限额计算。' : '计算完成；未确认新能源减免资格时按全额计税。');
U.track('calc_result', { tool: 'buy-car', success: true, resultType: m.taxReductionEligible ? 'nev-reduction' : 'full-tax', energy: m.energyType });
}
function copyText(text) {
if (window.navigator && window.navigator.clipboard && window.navigator.clipboard.writeText) {
return window.navigator.clipboard.writeText(text).then(function () { return true; }, function () { return false; });
}
return new window.Promise(function (resolve) {
var area = document.createElement('textarea');
area.value = text;
area.setAttribute('readonly', '');
area.style.position = 'fixed';
area.style.opacity = '0';
document.body.appendChild(area);
area.select();
var ok = false;
try { ok = document.execCommand('copy'); } catch (error) { ok = false; }
document.body.removeChild(area);
resolve(ok);
});
}
form.addEventListener('submit', function (event) {
event.preventDefault();
show(Tools.buyCar.calculate(readInput()));
});
form.addEventListener('input', function () {
syncEnergyFields();
syncCostToggles();
clearResult();
});
form.addEventListener('change', function () {
syncEnergyFields();
syncCostToggles();
clearResult();
});
$('bc-copy').addEventListener('click', function () {
if (!lastResult) { status('请先完成一次测算。', true); return; }
var m = lastResult.metrics;
var lines = [
'买车全攻略测算',
'购置日期：' + m.purchaseDate,
'含税开票价格：' + U.money(m.invoicePrice),
'车辆购置税：' + U.money(m.purchaseTax) + '（减税 ' + U.money(m.taxReduction) + '）',
'车贷月供：' + U.money(m.monthlyPayment),
'签约前现金需求：' + U.money(m.cashUpfront),
'落地价格：' + U.money(m.landingPrice),
'月均用车成本：' + U.money(m.monthlyOwnershipCost),
'全款持有期总成本：' + U.money(m.fullCashOwnershipTotal),
'贷款持有期总成本：' + U.money(m.loanOwnershipTotal),
'期末结清剩余本金：' + U.money(m.remainingPrincipalAtSale),
'政策快照：' + lastResult.source.version + '，核验至 ' + lastResult.source.effectiveDate,
'结果仅为静态估算，实际以发票、税务机关、银行与保险报价为准。',
];
copyText(lines.join('\n')).then(function (ok) {
status(ok ? '测算摘要已复制。' : '复制失败，请手动选择结果文本。', !ok);
});
});
$('bc-export').addEventListener('click', function () {
if (!lastResult) { status('请先完成一次测算。', true); return; }
var exported = Core.csv.download('买车成本测算.csv', lastResult.details.map(function (item) {
return [item.label, typeof item.value === 'number' ? U.round(item.value, 2) : item.value, item.note];
}), ['项目', '数值', '单位或说明']);
status(exported ? '已导出当前测算明细。' : '导出失败，请检查浏览器下载权限。', !exported);
U.track('export_result', { tool: 'buy-car', success: exported });
});
syncEnergyFields();
syncCostToggles();
}
if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', boot);
else boot();
})();
